changeSet.sql:
ALTER TABLE actions RENAME COLUMN metadata TO availability;

UPDATE actions
SET guidance_url = availability->>'guidance_link'
WHERE availability IS NOT NULL AND jsonb_exists(availability, 'guidance_link');

UPDATE actions
SET availability = jsonb_build_object('type', availability->'available_area_type')
WHERE availability IS NOT NULL
  AND jsonb_exists(availability, 'available_area_type');
